Object? _intersectProjection(Object? value, List<Object?> views) {
  if (views.isEmpty) return value;
  if (value is Map<String, Object?> &&
      views.every((v) => v is Map<String, Object?>)) {
    final maps = views.cast<Map<String, Object?>>();
    return {
      for (final entry in value.entries)
        if (maps.every((m) => m.containsKey(entry.key)))
          entry.key: _intersectProjection(entry.value, [
            for (final m in maps) m[entry.key],
          ]),
    };
  }
  if (value is List<Object?> &&
      views.every((v) => v is List<Object?> && v.length == value.length)) {
    final lists = views.cast<List<Object?>>();
    return [
      for (var i = 0; i < value.length; i++)
        _intersectProjection(value[i], [for (final list in lists) list[i]]),
    ];
  }
  return value;
}

Object? _copyJson(Object? value) {
  return switch (value) {
    Map<String, Object?> map => map.map(
      (key, item) => MapEntry(key, _copyJson(item)),
    ),
    List<Object?> list => list.map(_copyJson).toList(),
    null || bool() || String() => value,
    num() when value.isFinite => value,
    _ => throw const FormatException('Expected a JSON value.'),
  };
}
